				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$$ \begin{array}{@{}rcl@{}} m_{1}&:=&\text{effectiveness / cost} = \frac{P_{R}}{P_{C}}, \end{array} $$\end{document}m1:=effectiveness / cost=PRPC,6\documentclass[12pt]{minimal}
				\usepackage{amsmath}
				\usepackage{wasysym} 
				\usepackage{amsfonts} 
				\usepackage{amssymb} 
